            "solution": "<?php\ndeclare(strict_types=1);\n\nnamespace Acme\\Tax\\Unified;\n\n/**\n * Unified tax calculator — brackets are now a parameter\n */\nclass TaxCalculator\n{\n    public function calculateTax(float $income, array $brackets): array\n    {\n        $totalTax = 0.0;\n        $remaining = $income;\n        $effectiveRate = 0.0;\n\n        foreach ($brackets as $bracket) {\n            if ($remaining <= 0) {\n                break;\n            }\n            $threshold = $bracket['threshold'];\n            $rate = $bracket['rate'];\n            $taxable = min($remaining, $threshold);\n            $tax = $taxable * $rate;\n            $totalTax += $tax;\n            $remaining -= $taxable;\n        }\n\n        if ($income > 0) {\n            $effectiveRate = $totalTax / $income;\n        }\n\n        return [\n            'income' => $income,\n            'total_tax' => $totalTax,\n            'effective_rate' => $effectiveRate,\n            'net_income' => $income -